import{_ as n,o as a,c as e,aw as o}from"./chunks/framework.DLufY-ao.js";const m=JSON.parse('{"title":"Композиция","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/theory/programming/main/composition.md","filePath":"wiki/dev-commit/theory/programming/main/composition.md"}'),l={name:"wiki/dev-commit/theory/programming/main/composition.md"};function p(t,s,i,r,c,d){return a(),e("div",null,[...s[0]||(s[0]=[o(`<h1 id="композиция" tabindex="-1">Композиция <a class="header-anchor" href="#композиция" aria-label="Permalink to &quot;Композиция&quot;">​</a></h1><ul><li><p><strong>Композиция и Агрегация</strong> - расширение функционала класса за счет &quot;внедрения&quot; других классов</p></li><li><p>Об агрегировании также часто говорят как об «отношении принадлежности» по принципу «у машины есть корпус, колёса и двигатель»</p></li><li><p><strong>Агрегация (агрегирование по ссылке)</strong> - отношение «часть-целое» между двумя равноправными объектами, когда один объект (контейнер) имеет ссылку на другой объект. Оба объекта могут существовать независимо: если контейнер будет уничтожен, то его содержимое - нет</p></li><li><p><strong>Композиция (агрегирование по значению)</strong> - более строгий вариант агрегирования, когда включаемый объект может существовать только как часть класса. Если класс будет уничтожен, то и включённый объект тоже будет уничтожен. Объект не может выйти за рамки своего класса. Объект будет создаваться внутри класса при создании класса и будет уничтожаться перед уничтожением родительского класса</p></li><li><p><strong>Функциональная композиция</strong> - передача результа вызова одной функции в качестве аргумента другой функции</p></li><li><p>Агрегация: профессора - факультеты, профессора остаются жить после разрушения факультета</p></li><li><p>Композиция: университет - факультеты, факультеты без университета уничтожаются</p></li></ul><h3 id="наследование-и-композиция" tabindex="-1">Наследование и композиция <a class="header-anchor" href="#наследование-и-композиция" aria-label="Permalink to &quot;Наследование и композиция&quot;">​</a></h3><ul><li>Наследование - когда класс-наследник имеет все поля и методы родительского класса, и, как правило, добавляет какой-то новый функционал или/и поля</li><li>Наследование предполагает принадлежность к какой-то общности (похожесть). Наследуются атрибуты, т.е. возможности, другого класса, при этом объектов непосредственно родительского класса не создается</li><li>Минус наследования влияние родительского класса на дочерние</li></ul><hr><ul><li>Ассоциация (частные случаи: Композиция и Агрегация) – когда один класс включает в себя другой класс в качестве одного из полей</li><li>Композиция предполагает формирование целого из частей. При композиции класс-агрегатор создает объекты других классов</li></ul><h3 id="dependency-injection" tabindex="-1">Dependency Injection <a class="header-anchor" href="#dependency-injection" aria-label="Permalink to &quot;Dependency Injection&quot;">​</a></h3><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A626A4;">function</span><span style="color:#4078F2;"> makeCoffee</span><span style="color:#383A42;">(coffee) {}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A626A4;">function</span><span style="color:#4078F2;"> produceCoffee</span><span style="color:#383A42;">() {</span></span>
<span class="line"><span style="color:#A626A4;">    return</span><span style="color:#383A42;"> { </span><span style="color:#E45649;">iCoffee</span><span style="color:#0184BC;">:</span><span style="color:#986801;">true</span><span style="color:#383A42;"> }</span></span>
<span class="line"><span style="color:#383A42;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A626A4;">function</span><span style="color:#4078F2;"> barista</span><span style="color:#383A42;">(makeCoffee, produceCoffee) {</span></span>
<span class="line"><span style="color:#A626A4;">    let</span><span style="color:#383A42;"> coffee </span><span style="color:#0184BC;">=</span><span style="color:#4078F2;"> makeCoffee</span><span style="color:#383A42;">(</span><span style="color:#4078F2;">produceCoffee</span><span style="color:#383A42;">());</span></span>
<span class="line"><span style="color:#383A42;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#4078F2;">barista</span><span style="color:#383A42;">(makeCoffee, produceCoffee);</span></span></code></pre></div>`,8)])])}const y=n(l,[["render",p]]);export{m as __pageData,y as default};
